import{_ as o,a0 as l,w as p,s as r,ao as d,I as n,x as a,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"PyCaret：机器学习模型开发变得简单 | LCTT x X-CMD","titleTemplate":false,"description":"PyCaret：机器学习模型开发变得简单 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PyCaret：机器学习模型开发变得简单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PyCaret：机器学习模型开发变得简单 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220509 PyCaret- Machine Learning Model Development Made Easy","title":"PyCaret：机器学习模型开发变得简单","tag":"202205","desc":""},"relativePath":"202205/20220509 PyCaret- Machine Learning Model Development Made Easy.md","filePath":"[post].md"}'),h={name:"202205/20220509 PyCaret- Machine Learning Model Development Made Easy.md"};function c(g,e,u,m,k,b){const t=l("Link");return p(),r("div",null,[e[15]||(e[15]=d(`<h1 id="pycaret-机器学习模型开发变得简单" tabindex="-1">PyCaret：机器学习模型开发变得简单 <a class="header-anchor" href="#pycaret-机器学习模型开发变得简单" aria-label="Permalink to “PyCaret：机器学习模型开发变得简单”">​</a></h1><blockquote><p>在当今快节奏的数字世界中，机构们使用低代码/无代码（LC/NC）应用来快速构建新的信息系统。本文将介绍 PyCaret，这是一个用 Python 编写的低代码机器学习库。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Featured-image-of-pycaret-696x477.jpg" alt="Featured-image-of-pycaret"></p><p>PyCaret 是 R 编程语言中 Caret（<ruby>分类和回归训练<rt>Classification And REgression Training</rt></ruby>的缩写）包的 Python 版本，具有许多优点。</p><ul><li><strong>提高工作效率：</strong> PyCaret 是一个低代码库，可让你提高工作效率。由于花费更少的时间进行编码，你和你的团队现在可以专注于业务问题。</li><li><strong>易于使用：</strong> 这个简单易用的机器学习库将帮助你以更少的代码行执行端到端的机器学习实验。</li><li><strong>可用于商业：</strong> PyCaret 是一个可用于商业的解决方案。它允许你从选择的 notebook 环境中快速有效地进行原型设计。</li></ul><p>你可以在 Python 中创建一个虚拟环境并执行以下命令来安装 PyCaret 完整版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install pycaret [full]</span></span></code></pre></div><p>机器学习从业者可以使用 PyCaret 进行分类、回归、聚类、异常检测、自然语言处理、关联规则挖掘和时间序列分析。</p><h3 id="使用-pycaret-构建分类模型" tabindex="-1">使用 PyCaret 构建分类模型 <a class="header-anchor" href="#使用-pycaret-构建分类模型" aria-label="Permalink to “使用 PyCaret 构建分类模型”">​</a></h3><p>本文通过从 PyCaret 的数据仓库中获取 Iris 数据集来解释使用 PyCaret 构建分类模型。</p><p>我们将使用 Google Colab 环境使事情变得简单，并按照下面提到的步骤进行操作。</p><h4 id="步骤-1" tabindex="-1">步骤 1 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to “步骤 1”">​</a></h4><p>首先，通过给出以下命令安装 PyCaret：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install pycaret</span></span></code></pre></div><h4 id="步骤-2" tabindex="-1">步骤 2 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to “步骤 2”">​</a></h4><p>接下来，加载数据集，如图 2 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-1-loading-the-dataset.jpg" alt="Loading the data set"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from pycaret.datasets import get_data</span></span>
<span class="line"><span>dataset = get_data(&#39;iris&#39;) </span></span>
<span class="line"><span>（或者）</span></span>
<span class="line"><span>import pandas as pd </span></span>
<span class="line"><span>dataset = pd.read_csv(&#39;/path_to_data/file.csv&#39;)</span></span></code></pre></div><h4 id="步骤-3" tabindex="-1">步骤 3 <a class="header-anchor" href="#步骤-3" aria-label="Permalink to “步骤 3”">​</a></h4><p>现在设置 PyCaret 环境，如图 2 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-2-PyCaret-Environment-Setup.jpg" alt="PyCaret environment setup"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from pycaret.classification import *</span></span>
<span class="line"><span>clf1 = setup(data=dataset, target = ‘species’)</span></span></code></pre></div><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-3-PyCaret-Environment-Setup-Result.jpg" alt="PyCaret environment setup result"></p><p>使用 PyCaret 构建任何类型的模型，环境设置是最重要的一步。默认情况下，<code>setup()</code> 函数接受参数 <code>data</code>（Pandas 数据帧）和 <code>target</code>（指向数据集中的类标签变量）。<code>setup()</code> 函数的结果如图 3 所示。 <code>setup()</code> 函数默认将 70% 的数据拆分为训练集，30% 作为测试集，并进行数据预处理，如图 3 所示。</p><h4 id="步骤-4" tabindex="-1">步骤 4 <a class="header-anchor" href="#步骤-4" aria-label="Permalink to “步骤 4”">​</a></h4><p>接下来，找到最佳模型，如图 4 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-4-Finding-the-best-model.jpg" alt="Finding the best model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>best = compare_models()</span></span></code></pre></div><p>默认情况下，<code>compare_models()</code> 应用十倍交叉验证，并针对具有较少训练时间的不同分类器计算不同的性能指标，如准确度、AUC、召回率、精度、F1 分数、Kappa 和 MCC，如图 4 所示。通过将 <code>tubro=True</code> 传递给 <code>compare_models()</code> 函数，我们可以尝试所有分类器。</p><h4 id="步骤-5" tabindex="-1">步骤 5 <a class="header-anchor" href="#步骤-5" aria-label="Permalink to “步骤 5”">​</a></h4><p>现在创建模型，如图 5 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-5-Creating-the-model.jpg" alt="Creating the model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lda_model=create_model (‘lda’)</span></span></code></pre></div><p>线性判别分析分类器表现良好，如图 4 所示。因此，通过将 <code>lda</code> 传递给 <code>create_model()</code> 函数，我们可以拟合模型。</p><h4 id="步骤-6" tabindex="-1">步骤 6 <a class="header-anchor" href="#步骤-6" aria-label="Permalink to “步骤 6”">​</a></h4><p>下一步是微调模型，如图 6 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-6-Tuning-the-model.jpg" alt="Tuning the model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tuned_lda=tune_model(lda_model)</span></span></code></pre></div><p>超参数的调整可以提高模型的准确性。<code>tune_model()</code> 函数将线性判别分析模型的精度从 0.9818 提高到 0.9909，如图 7 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-7Tuned-model-details.jpg" alt="Tuned model details"></p><h4 id="步骤-7" tabindex="-1">步骤 7 <a class="header-anchor" href="#步骤-7" aria-label="Permalink to “步骤 7”">​</a></h4><p>下一步是进行预测，如图 8 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-8-Predictions-using-tuned-model.jpg" alt="Predictions using the tuned model"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>predictions=predict_model(tuned_lda)</span></span></code></pre></div><p><code>predict_model()</code> 函数用于对测试数据中存在的样本进行预测。</p><h4 id="步骤-8" tabindex="-1">步骤 8 <a class="header-anchor" href="#步骤-8" aria-label="Permalink to “步骤 8”">​</a></h4><p>现在绘制模型性能，如图 9 所示：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-9-Evaluating-and-ploting-the-model-performance-Confusion-Matrix.jpg" alt="Evaluating and plotting the model performance — confusion matrix"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>evaluate_model(tuned_lda)</span></span></code></pre></div><p><code>evaluate_model()</code> 函数用于以最小的努力开发不同的性能指标。你可以尝试它们并查看输出。</p><hr>`,51)),n("p",null,[e[1]||(e[1]=a("via: ",-1)),s(t,{href:"https://www.opensourceforu.com/2022/05/pycaret-machine-learning-model-development-made-easy/"},{default:i(()=>[...e[0]||(e[0]=[a("https://www.opensourceforu.com/2022/05/pycaret-machine-learning-model-development-made-easy/",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=a("作者：",-1)),s(t,{href:"https://www.opensourceforu.com/author/s-ratan/"},{default:i(()=>[...e[2]||(e[2]=[a("S Ratan Kumar",-1)])]),_:1}),e[7]||(e[7]=a(" 选题：",-1)),s(t,{href:"https://github.com/lkxed"},{default:i(()=>[...e[3]||(e[3]=[a("lkxed",-1)])]),_:1}),e[8]||(e[8]=a(" 译者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[4]||(e[4]=[a("geekpi",-1)])]),_:1}),e[9]||(e[9]=a(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[5]||(e[5]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[a("Linux中国",-1)])]),_:1}),e[14]||(e[14]=a(" 荣誉推出",-1))])])}const w=o(h,[["render",c]]);export{C as __pageData,w as default};
